# Generated by build.py from recipe.yml for recipe ftp-run-out-of-space-on-upload. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/backups' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'db.dump'), "pg_dump of 2026-11-20`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/backups/2026-11-19.dump'), "pg_dump of 2026-11-19`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--allow-uploads', '--list-directories', '--directory', 'site', '--fault', '"out-of-space;path=/backups"', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -T db.dump ftp://127.0.0.1:8080/backups/2026-11-20.dump } finally { Stop-Process $server0 }
